[ 351 ]
}
}
The EventBusSettings type defined previously describes HostName of the RabbitMQ
instance, User and Password of the user, and the EventQueue name to use to push
messages. Furthermore, we can proceed by defining the mediator handler for consuming
the ItemSoldOutEvent events by defining a new class in the Cart.Domain project:
using System;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Cart.Domain.Entities;
using Cart.Domain.Events;
using Cart.Domain.Repositories;
using MediatR;
namespace Cart.Domain.Handlers.Cart
{
public class ItemSoldOutEventHandler :
IRequestHandler<ItemSoldOutEvent>
{
private readonly ICartRepository _cartRepository;
public ItemSoldOutEventHandler(ICartRepository cartRepository)
{
_cartRepository = cartRepository;
}
public async Task<Unit> Handle(ItemSoldOutEvent @event,
CancellationToken cancellationToken)
{
var cartIds = _cartRepository.GetCarts().ToList();
var tasks = cartIds.Select(async x =>
{
var cart = await _cartRepository.GetAsync(new Guid(x));
await RemoveItemsInCart(@event.Id, cart);
});
await Task.WhenAll(tasks);
return Unit.Value;
}
private async Task RemoveItemsInCart(string itemToRemove,
CartSession cartSessionSession)
{
if (string.IsNullOrEmpty(itemToRemove)) return;
Implementing Worker Services Using .NET Core Chapter 14
[ 352 ]
var toDelete = cartSessionSession?.Items?.Where(x =>
x.CartItemId.ToString() ==
itemToRemove).ToList();

if (toDelete == null || toDelete.Count == 0) return;
foreach (var item in toDelete)
cartSessionSession.Items?.Remove(item);
await _cartRepository.AddOrUpdateAsync(cartSessionSession);
}
}
}
The previous ItemSoldOutEventHandler class implements the
IRequestHandler<T> interface that's provided by the MediatR package. This interface
contains the Handle method, which is the main entry point of the handler. A
new ItemSoldOutEventHandler instance will be executed when an event of
the ItemSoldOutEvent type is received by the cart
service. ItemSoldOutEventHandler depends on ICartRepository. Furthermore, the
RemoveItemsInCart method retrieves all of the carts stored in our repository, and it
removes the sold-out items every time it receives a message of
the ItemSoldOutEvent type.
